def compute(vars):
    options_balance = vars["v1"]
    weighted_average_exercise_price = vars["v2"]
    total_value_dollars = options_balance * weighted_average_exercise_price
    total_value_millions = total_value_dollars / 1000000.0

    return {
        "value": total_value_millions,
        "trace": {
            "options_balance": options_balance,
            "weighted_average_exercise_price": weighted_average_exercise_price,
            "total_value_dollars": total_value_dollars,
            "output_meta": {
                "currency": "USD",
                "scale": "millions",
                "unit": "currency"
            }
        }
    }
